import{_ as t,o as a,c as n,aB as i}from"./chunks/framework.BzieFrTe.js";const g=JSON.parse('{"title":"Development","description":"","frontmatter":{},"headers":[],"relativePath":"development.md","filePath":"development.md","lastUpdated":null}'),s={name:"development.md"};function o(l,e,r,p,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="Development" tabindex="-1">Development <a class="header-anchor" href="#Development" aria-label="Permalink to &quot;Development {#Development}&quot;">​</a></h1><h2 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├── Lazy.jl              # Main module definition and version checking</span></span>
<span class="line"><span>├── cli.jl               # Command-line interface and user interaction</span></span>
<span class="line"><span>├── fitting.jl           # Core photometric redshift fitting algorithms</span></span>
<span class="line"><span>├── io.jl                # I/O operations, caching, and data management</span></span>
<span class="line"><span>├── utils.jl             # Utilities (progress bars, memory estimation, formatting)</span></span>
<span class="line"><span>├── template_grid.jl     # Template grid construction and IGM/CGM modeling</span></span>
<span class="line"><span>├── writedata.py         # Python interface for FITS I/O (via PyCall)</span></span>
<span class="line"><span>├── example_params.toml  # Example parameter file (used by \`lazy params\`)</span></span>
<span class="line"><span>├── templates/           # SED template library</span></span>
<span class="line"><span>│   └── template_directory.toml</span></span>
<span class="line"><span>├── filter_files/        # Filter transmission curves</span></span>
<span class="line"><span>│   └── filter_directory.toml</span></span>
<span class="line"><span>└── igm_data/            # IGM attenuation model data (Inoue+2014)</span></span></code></pre></div><h3 id="Data-Flow" tabindex="-1">Data Flow <a class="header-anchor" href="#Data-Flow" aria-label="Permalink to &quot;Data Flow {#Data-Flow}&quot;">​</a></h3><ol><li><p><strong>Input</strong>: FITS catalog + TOML parameter file</p></li><li><p><strong>Template grid construction</strong> (<code>template_grid.jl</code>): Interpolate templates onto the redshift grid, apply IGM/CGM attenuation, integrate through filter bandpasses</p></li><li><p><strong>Fitting</strong> (<code>fitting.jl</code>): For each object, solve non-negative least squares at every redshift to find the best-fit template combination</p></li><li><p><strong>Output</strong> (<code>io.jl</code>): Write results to FITS or HDF5</p></li></ol><h3 id="Key-Algorithms" tabindex="-1">Key Algorithms <a class="header-anchor" href="#Key-Algorithms" aria-label="Permalink to &quot;Key Algorithms {#Key-Algorithms}&quot;">​</a></h3><ul><li><p><strong>Non-negative least squares</strong> (<code>NonNegLeastSquares.jl</code>): Ensures template coefficients are non-negative (physically motivated – you can&#39;t have negative flux contributions)</p></li><li><p><strong>IGM attenuation</strong>: Inoue et al. (2014) model with Lyman-series and continuum absorption</p></li><li><p><strong>CGM damping wing</strong>: Asada et al. (2024) Lyman-alpha damping wing model</p></li><li><p><strong>P(z) computation</strong>: exp(-0.5 * chi2) normalized over the redshift grid</p></li></ul><h2 id="Contributing" tabindex="-1">Contributing <a class="header-anchor" href="#Contributing" aria-label="Permalink to &quot;Contributing {#Contributing}&quot;">​</a></h2><p>Contributions are welcome, especially new filter transmission curves and template sets! If you&#39;ve added filters for an instrument or survey not yet included, or have a useful template set, please submit a PR to make them available to the community.</p><ol><li><p><strong>Fork</strong> the repository</p></li><li><p><strong>Create</strong> a feature branch: <code>git checkout -b feature-name</code></p></li><li><p><strong>Test</strong> your changes: <code>julia --project=. -e &quot;using Pkg; Pkg.test()&quot;</code></p></li><li><p><strong>Submit</strong> a pull request</p></li></ol><h2 id="Running-Tests" tabindex="-1">Running Tests <a class="header-anchor" href="#Running-Tests" aria-label="Permalink to &quot;Running Tests {#Running-Tests}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;using Pkg; Pkg.test()&quot;</span></span></code></pre></div><p>The test suite covers CLI parsing, template/filter directory integrity, CGM model physics, and spectroscopic redshift fixing.</p><h2 id="Extending-Lazy.jl" tabindex="-1">Extending Lazy.jl <a class="header-anchor" href="#Extending-Lazy.jl" aria-label="Permalink to &quot;Extending Lazy.jl {#Extending-Lazy.jl}&quot;">​</a></h2><h3 id="Adding-Templates" tabindex="-1">Adding Templates <a class="header-anchor" href="#Adding-Templates" aria-label="Permalink to &quot;Adding Templates {#Adding-Templates}&quot;">​</a></h3><p>See <a href="/Lazy.jl/v1/templates#Templates">Templates</a> for the full guide. In brief: add files to <code>src/templates/</code> and register them in <code>template_directory.toml</code>.</p><h3 id="Adding-Filters" tabindex="-1">Adding Filters <a class="header-anchor" href="#Adding-Filters" aria-label="Permalink to &quot;Adding Filters {#Adding-Filters}&quot;">​</a></h3><p>See <a href="/Lazy.jl/v1/filters#Filters">Filters</a> for the full guide. In brief: add transmission curves to <code>src/filter_files/</code> and register them in <code>filter_directory.toml</code>.</p><h3 id="Other-Extension-Points" tabindex="-1">Other Extension Points <a class="header-anchor" href="#Other-Extension-Points" aria-label="Permalink to &quot;Other Extension Points {#Other-Extension-Points}&quot;">​</a></h3><ul><li><p><strong>IGM models</strong>: Add attenuation data to <code>src/igm_data/</code> and implement the loader</p></li><li><p><strong>Template error functions</strong>: Add to <code>src/templates/template_error/</code></p></li><li><p><strong>Output formats</strong>: Extend I/O functions in <code>src/io.jl</code></p></li><li><p><strong>Fitting algorithms</strong>: Modify the core fitting loop in <code>src/fitting.jl</code></p></li></ul>`,20)])])}const m=t(s,[["render",o]]);export{g as __pageData,m as default};
